/** One phrase template per language ({x} filled per language), joined into the 8-language entry. */
const fill = (templates: string[], x: string[]): string[] => templates.map((s, i) => s.replace(/\{x\}/g, x[i]));
const same = (x: string): string[] => Array(8).fill(x);

// Zones: a direction word in each language, for the focus and swap commands.
const DIRECTIONS: Record<string, string[]> = {
  left: ['left', '왼쪽', '左', '左', '左', 'izquierda', 'gauche', 'esquerda'],
  right: ['right', '오른쪽', '右', '右', '右', 'derecha', 'droite', 'direita'],
  up: ['up', '위쪽', '上', '上', '上', 'arriba', 'haut', 'acima'],
  down: ['down', '아래쪽', '下', '下', '下', 'abajo', 'bas', 'abaixo'],
};
const FOCUS = ['focus {x}|move focus {x}|{x} pane|go {x}', '{x} 패널로 이동|{x} 패널 포커스|{x} 영역', '{x}のペインへ|{x}にフォーカス|{x}のゾーン', '聚焦{x}|移到{x}面板|{x}侧区域', '聚焦{x}|移到{x}面板|{x}側區域', 'enfocar {x}|ir al panel de {x}|zona de {x}', 'focus {x}|aller au volet {x}|zone {x}', 'focar {x}|ir ao painel {x}|zona {x}'];
const SWAP = ['swap {x}|swap with {x}|exchange {x} pane', '{x} 패널과 바꾸기|{x} 패널 교체|{x} 영역과 교환', '{x}のペインと入れ替え|{x}と交換|{x}と入れ替える', '与{x}面板交换|交换{x}|{x}面板对调', '與{x}面板交換|交換{x}|{x}面板對調', 'intercambiar con {x}|cambiar con {x}|intercambiar zona de {x}', 'échanger avec {x}|permuter {x}|échanger le volet {x}', 'trocar com {x}|trocar {x}|permutar painel {x}'];
for (const [dir, x] of Object.entries(DIRECTIONS)) {
  WORDS.push([[`pane.focus.${dir}`], fill(FOCUS, x)], [[`pane.swap.${dir}`], fill(SWAP, x)]);
}

// Numbered jumps: Go to tab 1 .. 9, Go to project 1 .. 9.
const TAB_N = ['tab {x}|go to tab {x}|switch to tab {x}', '탭 {x}|{x}번 탭|{x}번 탭으로 이동', 'タブ{x}|{x}番目のタブへ|タブ{x}に切り替え', '选项卡 {x}|第 {x} 个选项卡|切换到选项卡 {x}', '選項卡 {x}|第 {x} 個選項卡|切換到選項卡 {x}', 'pestaña {x}|ir a la pestaña {x}|cambiar a la pestaña {x}', 'onglet {x}|aller à l’onglet {x}|passer à l’onglet {x}', 'aba {x}|ir para a aba {x}|mudar para a aba {x}'];
const PROJECT_N = ['project {x}|go to project {x}|switch to project {x}', '프로젝트 {x}|{x}번 프로젝트|{x}번 프로젝트로 이동', 'プロジェクト{x}|{x}番目のプロジェクトへ|プロジェクト{x}に切り替え', '项目 {x}|第 {x} 个项目|切换到项目 {x}', '專案 {x}|第 {x} 個專案|切換到專案 {x}', 'proyecto {x}|ir al proyecto {x}|cambiar al proyecto {x}', 'projet {x}|aller au projet {x}|passer au projet {x}', 'projeto {x}|ir para o projeto {x}|mudar para o projeto {x}'];
for (let n = 1; n <= 9; n++) {
  WORDS.push([[`session.jump.${n}`], fill(TAB_N, same(String(n)))], [[`project.jump.${n}`], fill(PROJECT_N, same(String(n)))]);
}

const table = (i: number) => Object.fromEntries(WORDS.flatMap(([ids, words]) => ids.map((id) => [`palette.kw.${id}`, words[i]])));

export const en = table(0);
export const ko = table(1);
export const ja = table(2);
export const zhHans = table(3);
export const zhHant = table(4);
export const es = table(5);
export const fr = table(6);
export const pt = table(7);
